items.solution:
function buildStorageKey(originalName, generateId) {
  const dotIndex = originalName.lastIndexOf('.');
  const hasExtension = dotIndex !== -1 && dotIndex !== originalName.length - 1;
  const id = generateId();
  if (!hasExtension) return id;
  const extension = originalName.slice(dotIndex).toLowerCase();
  return `${id}${extension}`;
}

